def transform(grid):
    # The bottom row provides a sequence. At each singleton, lay that
    # sequence horizontally from the singleton, truncated by grid edges;
    # the marker is sequence entry matching its color.
    h, w = len(grid), len(grid[0])
    seq = [v for v in grid[-1] if v]
    out = [[0 for _ in row] for row in grid]
    out[-1] = grid[-1][:]
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color and color in seq:
                start = c - seq.index(color)
                for i, value in enumerate(seq):
                    x = start + i
                    if 0 <= x < w:
                        out[r][x] = value
    return out

